        recordBest(next, bestRef, setBestScores);
        publish(`Pair found. All pairs found in ${next.moves} moves and ${formatElapsedTime(next.elapsedMs)}.`);
      } else {
        const pairs = matchedPairCount(next);
        publish(`Pair found. ${pairs} ${pairs === 1 ? 'pair' : 'pairs'} matched.`);
