import { useCallback, useEffect, useRef, useState, type MutableRefObject } from 'react';
import { advanceGame, isWon, SELECTION_KIND, type GameState } from '../state.ts';
import { accumulateMilliseconds } from './whole-time.ts';

export interface SessionClock {
  flush(): GameState;
  reset(): void;
}

export function useSessionClock(
  game: GameState,
  gameRef: MutableRefObject<GameState>,
  pausedRef: MutableRefObject<boolean>,
  paused: boolean,
  revision: number,
  commit: (game: GameState) => void,
): SessionClock {
  const activeRevision = useRef(revision);
  const lastNow = useRef(0);
  const remainder = useRef(0);
  const visible = useRef(false);
  const deadline = useRef({ key: '', at: 0 });
  const [visibilityVersion, setVisibilityVersion] = useState(0);
  activeRevision.current = revision;

  const flushRevision = useCallback((expectedRevision: number): GameState => {
    if (expectedRevision !== activeRevision.current) return gameRef.current;
    const now = performance.now();
    const delta = Math.max(0, now - lastNow.current);
    lastNow.current = now;
    const current = gameRef.current;
    if (!visible.current || pausedRef.current || !current.started || isWon(current)) return current;

    const chunk = accumulateMilliseconds(delta, remainder.current);
    remainder.current = chunk.remainder;
    if (chunk.wholeMilliseconds > 0) {
      const next = advanceGame(current, chunk.wholeMilliseconds);
      if (next !== current) commit(next);
    }
    return gameRef.current;
  }, [commit, gameRef, pausedRef]);

  const flush = useCallback(() => flushRevision(activeRevision.current), [flushRevision]);

  const reset = useCallback(() => {
    lastNow.current = performance.now();
    remainder.current = 0;
  }, []);

  useEffect(() => {
    const expectedRevision = revision;
    lastNow.current = performance.now();
    remainder.current = 0;
    visible.current = !document.hidden;
    const interval = window.setInterval(() => flushRevision(expectedRevision), 100);

    const onVisibilityChange = () => {
      if (expectedRevision !== activeRevision.current) return;
      flushRevision(expectedRevision);
      visible.current = !document.hidden;
      lastNow.current = performance.now();
      setVisibilityVersion((value) => value + 1);
    };
    document.addEventListener('visibilitychange', onVisibilityChange);
    return () => {
      window.clearInterval(interval);
      document.removeEventListener('visibilitychange', onVisibilityChange);
    };
  }, [flushRevision, revision]);

  useEffect(() => {
    const selection = game.selection;
    if (selection.kind !== SELECTION_KIND.mismatch || paused || !visible.current) {
      deadline.current = { key: '', at: 0 };
      return;
    }
    const key = `${revision}:${selection.first}:${selection.second}`;
    if (deadline.current.key !== key) {
      deadline.current = { key, at: lastNow.current + selection.remainingMs - remainder.current };
    }
    let cancelled = false;
    let timer = 0;
    const schedule = () => {
      const delay = Math.max(0, deadline.current.at - performance.now());
      timer = window.setTimeout(() => {
        if (cancelled) return;
        flushRevision(revision);
        if (cancelled || revision !== activeRevision.current || !visible.current || pausedRef.current) return;
        const current = gameRef.current.selection;
        if (current.kind !== SELECTION_KIND.mismatch || deadline.current.key !== key) return;
        if (current.remainingMs > 0) {
          deadline.current = { key, at: lastNow.current + current.remainingMs - remainder.current };
          schedule();
        }
      }, delay);
    };
    schedule();
    return () => {
      cancelled = true;
      window.clearTimeout(timer);
    };
  }, [flushRevision, game, gameRef, paused, pausedRef, revision, visibilityVersion]);

  return { flush, reset };
}
import { GRID_SIZES, isGridSize, type GridSize } from '../board.ts';
import { MAX_MOVES } from '../state.ts';

export interface StoragePort {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

const PREFERENCE_KEY = 'neon-pairs.preferences.v1';
const BEST_KEY = 'neon-pairs.best.v1';

export function readSavedSize(storage: StoragePort | null = browserStorage()): GridSize | null {
  try {
    if (storage === null) return null;
    const raw = storage.getItem(PREFERENCE_KEY);
    if (raw === null) return null;
    const value: unknown = JSON.parse(raw);
    return isRecord(value) && isGridSize(value.gridSize) ? value.gridSize : null;
  } catch {
    return null;
  }
}

export function saveSize(size: GridSize, storage: StoragePort | null = browserStorage()): void {
  try {
    storage?.setItem(PREFERENCE_KEY, JSON.stringify({ gridSize: size }));
  } catch {
    return;
  }
}

export function readBestScores(storage: StoragePort | null = browserStorage()): ReadonlyMap<GridSize, number> {
  const scores = new Map<GridSize, number>();
  try {
    if (storage === null) return scores;
    const raw = storage.getItem(BEST_KEY);
    if (raw === null) return scores;
    const value: unknown = JSON.parse(raw);
    if (!isRecord(value)) return scores;
    for (const size of GRID_SIZES) {
      const score = value[String(size)];
      if (Number.isSafeInteger(score) && typeof score === 'number' && score >= 0 && score <= MAX_MOVES) {
        scores.set(size, score);
      }
    }
  } catch {
    return new Map();
  }
  return scores;
}

export function saveBestScore(size: GridSize, moves: number, storage: StoragePort | null = browserStorage()): void {
  if (!Number.isSafeInteger(moves) || moves < 0 || moves > MAX_MOVES) return;
  try {
    if (storage === null) return;
    const scores = new Map(readBestScores(storage));
    const current = scores.get(size);
    if (current !== undefined && current <= moves) return;
    scores.set(size, moves);
    storage.setItem(BEST_KEY, JSON.stringify(Object.fromEntries(scores)));
  } catch {
    return;
  }
}

function browserStorage(): StoragePort | null {
  try {
    return typeof window === 'undefined' ? null : window.localStorage;
  } catch {
    return null;
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}
import type { GridSize } from '../board.ts';

const MAX_SEED = 2_147_483_646;

export function newBoardCode(size: GridSize, previousSeed?: number): string {
  const values = new Uint32Array(1);
  let value: number;
  try {
    value = window.crypto.getRandomValues(values)[0] ?? 0;
  } catch {
    value = Math.floor(Math.random() * MAX_SEED);
  }
  let seed = (value % MAX_SEED) + 1;
  if (seed === previousSeed) seed = seed === MAX_SEED ? 1 : seed + 1;
  return `np1-${size}-${seed}`;
}
import type { MutableRefObject } from 'react';
import type { GridSize } from '../board.ts';
import type { GameState } from '../state.ts';
import { saveBestScore } from './storage.ts';

export function recordBestScore(
  game: GameState,
  bestRef: MutableRefObject<ReadonlyMap<GridSize, number>>,
  setBestScores: (value: ReadonlyMap<GridSize, number>) => void,
): void {
  const size = game.board.size;
  const existing = bestRef.current.get(size);
  if (existing !== undefined && existing <= game.moves) return;
  const next = new Map(bestRef.current);
  next.set(size, game.moves);
  bestRef.current = next;
  setBestScores(next);
  saveBestScore(size, game.moves);
}
import { formatElapsedTime, isWon, matchedPairCount, SELECTION_KIND, type GameState } from '../state.ts';

export interface TurnAnnouncement {
  readonly text: string;
  readonly completed: boolean;
}

export function turnAnnouncement(before: GameState, after: GameState): TurnAnnouncement | null {
  if (before.selection.kind !== SELECTION_KIND.one || after.selection.kind === SELECTION_KIND.one) return null;
  if (after.selection.kind === SELECTION_KIND.mismatch) {
    return { text: 'No match. Cards close after a short pause.', completed: false };
  }
  if (after.matched.length === before.matched.length) return null;
  if (isWon(after)) {
    return {
      text: `Pair found. All pairs found in ${after.moves} moves and ${formatElapsedTime(after.elapsedMs)}.`,
      completed: true,
    };
  }
  const pairs = matchedPairCount(after);
  return { text: `Pair found. ${pairs} ${pairs === 1 ? 'pair' : 'pairs'} matched.`, completed: false };
}
"}

