textarea:focus-visible,
summary:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.game-shell {
  width: min(100%, 1120px);
  min-width: 0;
  margin: 0 auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.game-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.game-header h1,
.game-header p,
.game-summary p,
.win-banner,
.paused-note {
  margin: 0;
}

.game-header h1 {
  font-size: 24px;
  line-height: 32px;
  letter-spacing: 0.02em;
}

.eyebrow {
  color: var(--secondary);
  font-size: 14px;
}

.play-panel {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.game-summary {
  width: 100%;
  display: flex;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
  font-variant-numeric: tabular-nums;
}

.win-banner {
  padding: 8px 16px;
  border: 1px solid var(--green);
  border-radius: 8px;
  color: var(--text);
  text-align: center;
}

.win-banner--pulse {
  animation: victory-pulse 600ms ease-out 1;
}

@keyframes victory-pulse {
  0% { transform: scale(1); }
  45% { transform: scale(1.025); }
  100% { transform: scale(1); }
}

.paused-note {
  color: var(--secondary);
  font-size: 14px;
}

.resume-button {
  align-self: center;
}

.screen-reader-status {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

@media (max-width: 560px) {
  .game-header {
    align-items: stretch;
  }

  .game-summary {
    gap: 8px 16px;
    justify-content: space-between;
  }
}

