import { chromium } from '@playwright/test';
const browser = await chromium.launch({headless:true});
const page = await browser.newPage({viewport:{width:360,height:800}});
await page.goto('file:///work/dist/index.html');
const board = page.getByRole('group', {name:'4 by 4 memory board'});
const cards = board.getByRole('button');
if (await cards.count() !== 16) throw new Error('Expected the default 4x4 board.');
if (await page.locator('.face-artwork').count() !== 0) throw new Error('A hidden face was mounted.');
if (await cards.nth(0).getAttribute('aria-label') !== 'Row 1, column 1, closed') throw new Error('Hidden name is incorrect.');
await cards.nth(0).click();
const firstName = await cards.nth(0).getAttribute('aria-label');
if (!firstName?.includes('revealed')) throw new Error('Card did not reveal.');
if (await page.locator('.face-artwork').count() !== 1) throw new Error('Only one face should be mounted.');
await page.keyboard.press('ArrowLeft');
if (await page.evaluate(() => (document.activeElement).getAttribute('aria-label')) !== firstName) throw new Error('Left edge movement escaped the row.');
await page.getByText('Reproduce a game').click();
await page.getByLabel('Board code').fill('np1-4-1');
await page.getByRole('button', {name:'Load board'}).click();
if (await cards.nth(0).getAttribute('aria-label') !== 'Row 1, column 1, closed') throw new Error('Loaded board did not reset.');
if (await cards.nth(0).getAttribute('tabindex') !== '0') throw new Error('Loaded board tab stop did not reset.');
