await page.getByLabel('Snapshot JSON').fill(JSON.stringify(snapshot));
await page.getByRole('button',{name:'Load snapshot'}).click();
if (await page.getByRole('button',{name:'Resume'}).count() !== 1) throw new Error('Unfinished import did not pause.');
await cards.nth(10).click();
if (await cards.nth(10).getAttribute('aria-label') !== 'Row 3, column 3, closed') throw new Error('Paused snapshot accepted a reveal.');
await page.getByRole('button',{name:'Resume'}).click();
if (await page.evaluate(() => (document.activeElement).getAttribute('aria-label')) !== 'Row 3, column 3, closed') throw new Error('Resume did not restore board focus.');
if (await page.getByRole('button',{name:'Resume'}).count() !== 0) throw new Error('Resume remained after continuing.');
console.log(JSON.stringify({browser:browser.version(),boardCards:await cards.count(),firstDealFace:firstName,firstDealHiddenFaces:0,resumedFocus:'Row 3, column 3, closed',outerWidth:await page.evaluate(()=>document.documentElement.scrollWidth)}));
await browser.close();
