test('captures a 44px grayscale sheet of all 128 rendered face identities', async ({ page }) => {
  await page.setViewportSize({ width: 1280, height: 800 });
  await page.goto('/');
  const board = parseBoardCode('np1-16-1');
  if (board === null) throw new Error('The fixture board should be valid.');
  await loadBoard(page, board.boardCode);
  await openReproduction(page);
  await page.getByLabel('Snapshot JSON').fill(await completedSnapshot(16));
  await page.getByRole('button', { name: 'Load snapshot' }).click();

  const identities = new Map<number, string>();
  board.deck.forEach((_face, index) => {
    const face = board.deck[index];
    if (face !== undefined && !identities.has(face)) identities.set(face, `Row ${Math.floor(index / 16) + 1}, column ${(index % 16) + 1}, ${faceName(face)}, matched`);
  });
  const samples: Array<{ name: string; svg: string; face: number }> = [];
  for (const [face, name] of [...identities].sort(([left], [right]) => left - right)) {
    const svg = await page.getByRole('button', { name }).locator('svg').evaluate((element) => element.outerHTML);
    samples.push({ name, svg, face });
  }
  expect(samples).toHaveLength(128);
  expect(samples.map((sample) => sample.name)).toHaveLength(128);
  const markup = samples.map((sample) => `<div class="tile" aria-label="${sample.name}">${sample.svg}</div>`).join('');
  await mkdir('evidence', { recursive: true });
  await page.setContent(`<style>
    *{box-sizing:border-box}body{margin:0;padding:16px;background:#090B14;color:#F4F6FF;
    font:14px system-ui,sans-serif}.sheet{display:grid;grid-template-columns:repeat(16,44px);gap:6px;width:max-content}
    .tile{display:grid;width:44px;height:44px;place-items:center;border:2px solid #757C9A;border-radius:8px;
    padding:4px;background:#111625}.tile svg{width:32px;height:32px;filter:grayscale(1)}.face-marker{stroke:#111625;stroke-width:3}
  </style><main class="sheet">${markup}</main>`);
  await page.screenshot({ path: 'evidence/faces-grayscale-44.png', fullPage: true });
});

test('supports a touch-enabled context for scrolling and tapping the 16x16 board', async ({ browser }: { browser: Browser }) => {
  const context = await browser.newContext({ viewport: { width: 360, height: 800 }, isMobile: true, hasTouch: true });
  const page = await context.newPage();
  try {
    await page.goto('http://127.0.0.1:4173/');
    await loadBoard(page, 'np1-16-1');
    const area = page.locator('.board-scroll');
    const bounds = await area.boundingBox();
    if (bounds === null) throw new Error('The board should have a visible scroll area.');
    const session = await context.newCDPSession(page);
    const x = bounds.x + bounds.width / 2;
    const start = bounds.y + bounds.height * 0.75;
    const end = Math.max(bounds.y + 12, bounds.y + bounds.height * 0.2);
    await session.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ id: 1, x, y: start }] });
    await session.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ id: 1, x, y: end }] });
    await session.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
    const scrollTop = await area.evaluate((element) => element.scrollTop);
    expect(scrollTop).toBeGreaterThan(0);
    const last = page.getByRole('button', { name: 'Row 16, column 16, closed' });
    await last.tap();
    await expect(page.getByRole('button', { name: /Row 16, column 16, .*revealed/ })).toBeVisible();
    expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBeLessThanOrEqual(360);
  } finally {
    await context.close();
  }
});

