    await denied.goto('/');
    await denied.getByRole('button', { name: 'Row 1, column 1, closed' }).click();
    await expect(denied.getByRole('button', { name: /Row 1, column 1, .*revealed/ })).toBeVisible();
  } finally {
    await denied.close();
  }
});

